        dst = packet.get("dst_ip", "")
        port = packet.get("dst_port", 0)
        src_targets.setdefault(src, set()).add((dst, port))

    for packet in packet_log:
        reasons: list[str] = []
        port = packet.get("dst_port", 0)
        src = packet.get("src_ip", "")

        if port in {22, 23, 3389}:
            reasons.append("sensitive_port")

        if packet.get("bytes", 0) > 10_000_000:
            reasons.append("large_transfer")

        if len(src_targets.get(src, set())) > 20:
            reasons.append("possible_scan")

        if reasons:
            flagged = dict(packet)
            flagged["reasons"] = reasons
            suspicious.append(flagged)

