def detect_brute_force(auth_log: list[dict], threshold: int = 5) -> list[str]:
    counts: dict[str, int] = {}

    for entry in auth_log:
        ip = entry.get("ip")
        if not ip:
            continue

        failed = (
            not entry.get("success", True)
            or entry.get("status") in {"failed", "failure", "denied"}
        )

        if failed:
            counts[ip] = counts.get(ip, 0) + 1

    return [ip for ip, count in counts.items() if count >= threshold]
