import stat

def find_writable_files(directory: str) -> list[str]:
    results = []
    for root, _, files in os.walk(directory):
        for f in files:
            path = os.path.join(root, f)
            try:
                st = os.lstat(path)
                if os.access(path, os.W_OK):
                    if st.st_mode & stat.S_ISUID or st.st_mode & stat.S_ISGID:
                        results.append(path)
                    elif st.st_mode & stat.S_IWOTH:
                        results.append(path)
            except (OSError, PermissionError):
                continue
    return results
